DROP TABLE IF EXISTS `usuario_credenciais`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuario_credenciais` (
  `usuario_id` int unsigned NOT NULL,
  `senha_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'password_hash(); nunca texto puro',
  `exigir_troca_senha` tinyint(1) NOT NULL DEFAULT '1',
  `tentativas_login` smallint unsigned NOT NULL DEFAULT '0',
  `bloqueado_ate` datetime DEFAULT NULL COMMENT 'Bloqueio temporario apos tentativas falhas',
  `ultimo_login` datetime DEFAULT NULL,
  `senha_alterada_em` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`usuario_id`),
  CONSTRAINT `fk_credenciais_usuario` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_credenciais_troca` CHECK ((`exigir_troca_senha` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
