DROP TABLE IF EXISTS `usuarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuarios` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `nome` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(254) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Sempre em minusculas; futuro identificador de login',
  `matricula` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Texto: preserva zeros a esquerda',
  `cargo_id` smallint unsigned NOT NULL,
  `lotacao_id` smallint unsigned NOT NULL,
  `perfil` enum('ADMINISTRADOR','GESTOR','USUARIO') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USUARIO' COMMENT 'Perfil de acesso',
  `data_nascimento` date DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `inativado_em` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_usuarios_email` (`email`),
  UNIQUE KEY `uq_usuarios_matricula` (`matricula`),
  KEY `ix_usuarios_nome` (`nome`),
  KEY `ix_usuarios_ativo` (`ativo`),
  KEY `ix_usuarios_cargo` (`cargo_id`),
  KEY `ix_usuarios_lotacao` (`lotacao_id`),
  KEY `ix_usuarios_perfil` (`perfil`),
  CONSTRAINT `fk_usuarios_cargo` FOREIGN KEY (`cargo_id`) REFERENCES `cargos` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_usuarios_lotacao` FOREIGN KEY (`lotacao_id`) REFERENCES `lotacoes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_usuarios_ativo` CHECK ((`ativo` in (0,1)))
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
